10	/**
11	 * Rejects a create-owner request once the maximum number of owners ({@value #DAILY_LIMIT})
12	 * have already been registered today, responding 429, before {@link BuildOwner} persists
13	 * one over the limit. Registrations are counted via {@link Registrations}.
14	 */
15	public class EnsureUnderDailyLimit {
16	
17	    static final int DAILY_LIMIT = 100;
18	
19	    public void service(OwnerRepository ownerRepository) throws DailyLimitExceededException {
20	        LocalDate today = LocalDate.now();
21	        if (Registrations.countOn(ownerRepository, today) >= DAILY_LIMIT) {
22	            throw new DailyLimitExceededException(today, DAILY_LIMIT);
23	        }
24	    }
25	}
