1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Shared registration-date logic. An owner is registered on the calendar date in their
9	 * {@code registrationDate} field, so every rule that reasons about a day's registrations
10	 * (such as the daily creation limit) counts the same set of owners.
11	 */
12	final class Registrations {
13	
14	    private Registrations() {
15	    }
16	
17	    /**
18	     * The number of existing owners registered on the given date.
19	     */
20	    static long countOn(OwnerRepository ownerRepository, LocalDate date) {
21	        return ownerRepository.findAll().stream()
22	                .filter(existing -> date.equals(existing.getRegistrationDate()))
23	                .count();
24	    }
25	}
