5	/**
6	 * Thrown when a create-owner request arrives after the maximum number of owners have
7	 * already been registered on the current day, so no more may be created today. Handled by
8	 * {@link DailyLimitExceededExceptionHandler}, which responds 429.
9	 */
10	public class DailyLimitExceededException extends Exception {
11	
12	    private final LocalDate date;
13	
14	    private final int limit;
15	
16	    public DailyLimitExceededException(LocalDate date, int limit) {
17	        super("Daily owner limit reached (" + limit + " owners) for " + date);
18	        this.date = date;
19	        this.limit = limit;
20	    }
21	
22	    public LocalDate getDate() {
23	        return this.date;
24	    }
25	
26	    public int getLimit() {
27	        return this.limit;
28	    }
29	}
