9	public class DailyLimitExceededExceptionHandler {
10	
11	    public void handle(@Parameter DailyLimitExceededException ex,
12	            ObjectResponse<ResponseEntity<ProblemDetail>> response) {
13	        ProblemDetail detail = ProblemDetails.build(ex, HttpStatus.TOO_MANY_REQUESTS,
14	                "The maximum number of owners for today has already been reached");
15	        response.send(ResponseEntity.status(HttpStatus.TOO_MANY_REQUESTS).body(detail));
16	    }
17	}
